-- 0045_aws_subject.sql
-- New top-level study subject "AWS" (alongside English, PMP, Pentest), covering
-- cloud architecture fundamentals: VPC networking (Internet Gateway, public/
-- private subnets, EC2 without a public IP), compute (EC2 + Docker), storage
-- (S3), in-VPC data services (ElastiCache, MSK/Kafka), PCI-DSS/SOC 2
-- architecture considerations, and Cloudflare in front of an AWS origin. Same
-- structure as the pentest subject (0019/0022): concept decks + an mcq
-- practice deck + a step-by-step command-typing "labs" deck (kind='lab').

INSERT INTO subjects (slug, name, description, sort_order) VALUES
  ('aws', 'AWS', 'AWS cloud architecture: networking, compute, storage, data, PCI/SOC 2, Cloudflare', 4)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO decks (subject_id, slug, name, description, default_kind, sort_order)
SELECT s.id, d.slug, d.name, d.description, d.kind, d.sort_order
FROM (VALUES
  ('networking', 'VPC & Networking', 'Internet Gateway, subnets, routing, security groups', 'concept', 1),
  ('compute', 'EC2 & Docker', 'EC2 instances, IAM roles, running Docker on EC2', 'concept', 2),
  ('storage', 'S3 Storage', 'Buckets, policies, encryption, access', 'concept', 3),
  ('data', 'ElastiCache & Kafka (MSK)', 'In-VPC caching and streaming data services', 'concept', 4),
  ('compliance', 'PCI-DSS & SOC 2', 'Architecture considerations for compliance', 'concept', 5),
  ('cdn_security', 'Cloudflare', 'DNS, SSL modes, WAF, protecting the AWS origin', 'concept', 6),
  ('practice', 'Practice questions', 'Exam-style multiple choice', 'mcq', 7),
  ('labs', 'Thực hành (Labs)', 'Các bài lab từng bước: gõ đúng lệnh/cấu hình mới qua bước tiếp theo', 'lab', 8)
) AS d(slug, name, description, kind, sort_order)
JOIN subjects s ON s.slug = 'aws'
ON CONFLICT (subject_id, slug) DO NOTHING;
INSERT INTO cards (deck_id, kind, front, payload, source)
SELECT d.id, 'concept', c.front, c.payload, 'seed'
FROM (VALUES
  ('networking', 'VPC (Virtual Private Cloud)', '{"back": "A private, isolated virtual network inside AWS where you launch resources (EC2, RDS...). You define its IP range (CIDR) and everything else lives inside it.", "note_vi": "Mạng riêng ảo trong AWS, bạn tự định nghĩa dải IP (CIDR) và mọi thứ khác (subnet, routing, gateway) nằm trong đó.", "example": "aws ec2 create-vpc --cidr-block 10.0.0.0/16"}'::jsonb),
  ('networking', 'Internet Gateway (IGW)', '{"back": "A VPC component that lets resources in a PUBLIC subnet reach the internet (and be reached from it), via a route table entry pointing 0.0.0.0/0 to the IGW.", "note_vi": "Thành phần cho phép resource trong subnet PUBLIC ra internet (và bị truy cập từ internet), qua route table trỏ 0.0.0.0/0 về IGW.", "example": "aws ec2 create-internet-gateway; aws ec2 attach-internet-gateway --vpc-id <vpc-id> --internet-gateway-id <igw-id>"}'::jsonb),
  ('networking', 'NAT Gateway', '{"back": "Lets resources in a PRIVATE subnet reach OUT to the internet without being reachable FROM the internet - one-way, unlike an Internet Gateway.", "note_vi": "Cho resource trong subnet PRIVATE ra internet được (vd apt update, pull Docker image) nhưng KHÔNG bị truy cập ngược từ internet vào - một chiều, khác với IGW.", "example": "Private-subnet route table: 0.0.0.0/0 -> nat-gateway-id (không phải igw-id)."}'::jsonb),
  ('networking', 'Public subnet vs Private subnet', '{"back": "The difference is purely the route table: a subnet is ''public'' if its route table sends 0.0.0.0/0 to an Internet Gateway. ''Private'' = no such route.", "note_vi": "Sự khác biệt chỉ nằm ở route table: subnet là ''public'' nếu route table có 0.0.0.0/0 trỏ về Internet Gateway. ''Private'' = không có route đó (ra ngoài, nếu có, phải qua NAT Gateway).", "example": "Một subnet có route NAT nhưng không có route IGW vẫn là private, dù CIDR trông có vẻ public."}'::jsonb),
  ('networking', 'EC2 không có Public IP', '{"back": "An EC2 launched in a private subnet with no Elastic IP / auto-assign public IP has NO direct internet-facing address - reachable only from inside the VPC (or via bastion/VPN/SSM).", "note_vi": "EC2 trong private subnet, không gán Elastic IP / không auto-assign public IP → không có địa chỉ internet trực tiếp nào - chỉ truy cập được từ trong VPC (hoặc qua bastion/VPN/SSM). Đây là pattern khuyến nghị cho app/DB server.", "example": "aws ec2 run-instances --subnet-id <private-subnet> --no-associate-public-ip-address ..."}'::jsonb),
  ('networking', 'AWS Systems Manager Session Manager', '{"back": "Lets you get a shell on an EC2 instance with NO public IP and NO open SSH port 22 - connects via the SSM Agent over an outbound HTTPS connection, not inbound SSH.", "note_vi": "Cho phép SSH vào EC2 KHÔNG có public IP và KHÔNG mở cổng 22 - kết nối qua SSM Agent (có sẵn trên Amazon Linux 2/2023) bằng HTTPS ra ngoài, không phải SSH vào.", "example": "aws ssm start-session --target <instance-id>"}'::jsonb),
  ('networking', 'Security Group vs Network ACL', '{"back": "Security Group = stateful firewall at the INSTANCE level (allow rules only; replies auto-allowed back). Network ACL = stateless firewall at the SUBNET level (allow+deny; replies need an explicit outbound rule too).", "note_vi": "Security Group: firewall stateful ở cấp INSTANCE (chỉ có allow rule; traffic trả lời tự được cho qua). Network ACL: firewall stateless ở cấp SUBNET (có cả allow và deny; traffic trả lời phải có rule outbound riêng).", "example": "Security Group inbound rule cho port 443 là đủ; NACL cần cả inbound VÀ outbound (ephemeral ports) tương ứng."}'::jsonb),
  ('networking', 'VPC Endpoint', '{"back": "Lets a private-subnet EC2 reach AWS services like S3 or DynamoDB directly over the AWS private network, instead of needing a NAT Gateway just for that traffic.", "note_vi": "Cho EC2 ở private subnet (không có route NAT/internet) vẫn gọi được dịch vụ AWS như S3, DynamoDB trực tiếp qua mạng nội bộ AWS, khỏi cần NAT Gateway chỉ để làm việc đó.", "example": "Gateway Endpoint cho S3 tránh được phí NAT Gateway data-transfer cho traffic S3."}'::jsonb),
  ('networking', 'Route table', '{"back": "Per-subnet rules deciding where traffic for a given destination CIDR goes next.", "note_vi": "Bảng quy tắc gắn với mỗi subnet, quyết định traffic tới 1 dải IP đích sẽ đi đâu tiếp (trong VPC, ra Internet Gateway, qua NAT Gateway, qua peering...).", "example": "10.0.0.0/16 -> local; 0.0.0.0/0 -> igw-xxxx (public) hoặc nat-xxxx (private)."}'::jsonb),
  ('compute', 'EC2 instance types', '{"back": "On-Demand (pay per hour/second, no commitment), Reserved/Savings Plans (cheaper, 1-3 year commitment), Spot (cheapest, can be reclaimed by AWS with short notice).", "note_vi": "On-Demand: trả theo giờ/giây, không ràng buộc. Reserved/Savings Plans: rẻ hơn, cam kết 1-3 năm. Spot: rẻ nhất, AWS có thể thu hồi bất cứ lúc nào - không dùng cho service chạy liên tục cần ổn định.", "example": "Spot phù hợp cho batch job; không dùng cho production database."}'::jsonb),
  ('compute', 'IAM role cho EC2 (instance profile)', '{"back": "Attach an IAM role to the EC2 instance itself so code running on it gets temporary, auto-rotated credentials - never hardcode a long-lived IAM access key/secret on an instance.", "note_vi": "Gắn IAM role trực tiếp vào EC2 để code chạy trên máy lấy được credential tạm, tự xoay vòng - KHÔNG BAO GIỜ hardcode access key/secret IAM user dài hạn lên máy.", "example": "aws ec2 associate-iam-instance-profile --instance-id <id> --iam-instance-profile Name=<role-name>"}'::jsonb),
  ('compute', 'EC2 User Data', '{"back": "A script passed at launch time that runs automatically once on first boot (as root) - used to bootstrap an instance without manual SSH-in.", "note_vi": "Script truyền vào lúc khởi tạo EC2, tự chạy 1 lần khi boot đầu tiên (với quyền root) - dùng để cài sẵn môi trường (cài package, start Docker, pull container) mà không cần SSH vào tay.", "example": "#!/bin/bash\\nyum update -y\\nyum install -y docker\\nsystemctl enable --now docker"}'::jsonb),
  ('compute', 'Chạy Docker trong EC2', '{"back": "Install the Docker engine on the instance, enable+start the daemon, then run containers normally - the EC2 is just a Linux host for Docker.", "note_vi": "Cài Docker engine lên EC2 (tên package khác nhau theo AMI), enable+start daemon, rồi chạy container như bình thường - EC2 chỉ đóng vai trò máy Linux chạy Docker, lệnh giống mọi nơi khác.", "example": "Amazon Linux 2023: sudo dnf install -y docker && sudo systemctl enable --now docker"}'::jsonb),
  ('compute', 'docker run - các cờ hay dùng', '{"back": "-d (detached/background), -p host:container (map port), -v host:container (mount volume), --name, --restart unless-stopped, -e (env var).", "note_vi": "-d chạy nền, -p map cổng host:container, -v mount volume, --name đặt tên, --restart unless-stopped tự chạy lại khi EC2 reboot/container crash, -e truyền env var.", "example": "docker run -d --name app -p 8080:80 -e NODE_ENV=production --restart unless-stopped myapp:latest"}'::jsonb),
  ('compute', 'Pull image riêng tư từ ECR', '{"back": "ECR requires an auth token (valid 12h) before docker pull/push - the IAM role on the EC2 needs ecr:GetAuthorizationToken + pull permissions.", "note_vi": "ECR cần token xác thực (hiệu lực 12h) trước khi pull/push - IAM role gắn vào EC2 cần quyền ecr:GetAuthorizationToken + quyền pull; không tự lưu mật khẩu đăng nhập ECR thủ công.", "example": "aws ecr get-login-password --region <region> | docker login --username AWS --password-stdin <acct>.dkr.ecr.<region>.amazonaws.com"}'::jsonb),
  ('storage', 'S3 Bucket', '{"back": "Object storage (not a filesystem/block device) - a flat namespace of objects inside a globally-unique-named bucket, in one region.", "note_vi": "Object storage (không phải filesystem/block device) - không gian phẳng chứa object (key/value + metadata) trong 1 bucket có tên duy nhất toàn cầu, nằm ở 1 region.", "example": "aws s3 mb s3://my-unique-bucket-name-2026 --region ap-southeast-1"}'::jsonb),
  ('storage', 'S3 Block Public Access', '{"back": "An account/bucket-level switch that overrides any bucket policy or ACL trying to make objects public - ON by default for new buckets.", "note_vi": "Cờ cấp account/bucket có thể ghi đè mọi bucket policy/ACL nào cố làm object public - mặc định BẬT cho bucket mới; là lớp bảo vệ quan trọng nhất chống rò rỉ dữ liệu S3 công khai do sơ ý.", "example": "aws s3api put-public-access-block --bucket my-bucket --public-access-block-configuration BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=true,RestrictPublicBuckets=true"}'::jsonb),
  ('storage', 'Bucket Policy vs IAM Policy', '{"back": "A bucket policy is attached to the BUCKET (controls who/what can access it, including cross-account). An IAM policy is attached to a USER/ROLE. For S3, both are checked.", "note_vi": "Bucket policy gắn vào BUCKET (kiểm soát ai/gì được truy cập, kể cả cross-account). IAM policy gắn vào USER/ROLE (kiểm soát identity đó được làm gì, trên mọi resource). Với S3, cả 2 đều được kiểm tra.", "example": "Một bucket policy deny access luôn thắng, dù IAM policy cho allow."}'::jsonb),
  ('storage', 'S3 Versioning', '{"back": "Keeps every past version of an object instead of overwriting it - protects against accidental overwrite/delete.", "note_vi": "Giữ lại mọi phiên bản cũ thay vì ghi đè mất - chống ghi đè/xóa nhầm (xóa chỉ thêm ''delete marker'', bản cũ vẫn còn).", "example": "aws s3api put-bucket-versioning --bucket my-bucket --versioning-configuration Status=Enabled"}'::jsonb),
  ('storage', 'S3 Server-Side Encryption (SSE-S3 vs SSE-KMS)', '{"back": "SSE-S3: AWS manages the key for you (simplest). SSE-KMS: you control the key via AWS KMS (rotation, access logging, per-key IAM permission) - needed for stricter compliance.", "note_vi": "SSE-S3: AWS tự quản lý key mã hóa (đơn giản nhất). SSE-KMS: bạn kiểm soát key qua AWS KMS (xoay key, log truy cập, phân quyền IAM theo từng key) - cần cho yêu cầu compliance chặt hơn.", "example": "Môi trường PCI/SOC 2 thường yêu cầu SSE-KMS để việc truy cập key cũng được audit."}'::jsonb),
  ('storage', 'Presigned URL', '{"back": "A temporary, time-limited URL you generate that lets someone upload/download ONE specific S3 object without AWS credentials or a public bucket.", "note_vi": "URL tạm, có thời hạn, bạn tự tạo (bằng credential của mình) để cho ai đó upload/download MỘT object S3 cụ thể mà KHÔNG cần họ có credential AWS hay phải public bucket.", "example": "aws s3 presign s3://my-bucket/report.pdf --expires-in 3600"}'::jsonb),
  ('data', 'ElastiCache tổng quan', '{"back": "A fully-managed in-memory cache (Redis or Memcached) that lives INSIDE your VPC only - no public endpoint by design.", "note_vi": "Dịch vụ cache in-memory được quản lý hoàn toàn (Redis hoặc Memcached), chỉ sống TRONG VPC của bạn - theo thiết kế không có endpoint public; chỉ resource cùng VPC (hoặc peering/kết nối) mới gọi được.", "example": "Một EC2 ở private subnet kết nối được ElastiCache; internet thì không bao giờ."}'::jsonb),
  ('data', 'ElastiCache: subnet group & security group', '{"back": "Deploy ElastiCache into a ''subnet group'' (usually private subnets) and gate access with a security group allowing the cache port only from your app''s security group.", "note_vi": "ElastiCache chạy trong 1 ''subnet group'' (thường là private subnet), kiểm soát truy cập bằng security group chỉ mở cổng cache (Redis 6379 / Memcached 11211) cho security group của app - không bao giờ mở cho 0.0.0.0/0.", "example": "Security group rule: allow 6379 from sg-app-xxxx only."}'::jsonb),
  ('data', 'Redis Cluster Mode: Enabled vs Disabled', '{"back": "Disabled = one primary + replicas, all data on one node. Enabled = data sharded across multiple node groups (scales beyond one node''s RAM, more complex client config).", "note_vi": "Cluster Mode Disabled: 1 primary + replica, toàn bộ data trên 1 node (đơn giản, bị giới hạn RAM 1 node). Cluster Mode Enabled: data được sharding qua nhiều node group (scale vượt RAM 1 node, client cần cấu hình phức tạp hơn).", "example": "Bắt đầu với Cluster Mode Disabled trừ khi đã biết trước cần sharding."}'::jsonb),
  ('data', 'MSK (Managed Streaming for Kafka) tổng quan', '{"back": "AWS''s managed Apache Kafka service - AWS runs the Kafka brokers for you; you still think in Kafka concepts (topics, partitions, producers/consumers).", "note_vi": "Dịch vụ Kafka được AWS quản lý - AWS vận hành broker Kafka cho bạn (patch, scale, giám sát); bạn vẫn làm việc với các khái niệm Kafka (topic, partition, producer/consumer) như bình thường.", "example": "aws kafka create-cluster --cluster-name my-cluster --kafka-version 3.5.1 --number-of-broker-nodes 3 ..."}'::jsonb),
  ('data', 'Kafka: Topic, Partition, Broker', '{"back": "Topic = a named stream of messages. Partition = a topic split into ordered partitions for parallelism (order guaranteed WITHIN a partition only). Broker = a Kafka server storing partitions.", "note_vi": "Topic: dòng message có tên. Partition: 1 topic được chia thành nhiều partition có thứ tự để chạy song song (thứ tự chỉ được đảm bảo TRONG 1 partition). Broker: máy chủ Kafka lưu partition.", "example": "3 partition cho phép 3 consumer trong group đọc song song; nhiều partition hơn không luôn đồng nghĩa nhiều throughput hơn."}'::jsonb),
  ('data', 'Kafka: Producer, Consumer, Consumer Group', '{"back": "Producer writes messages to a topic. Consumer reads them. A Consumer Group splits a topic''s partitions across its members so each message is processed by exactly ONE consumer in that group.", "note_vi": "Producer: ghi message vào topic. Consumer: đọc message. Consumer Group: chia các partition của 1 topic cho các member trong group, mỗi message chỉ được xử lý bởi ĐÚNG 1 consumer trong group đó.", "example": "Topic có 6 partition và consumer group có 3 member -> mỗi consumer xử lý 2 partition."}'::jsonb),
  ('data', 'MSK IAM Authentication', '{"back": "Lets clients authenticate to MSK using their IAM role/credentials instead of managing separate SASL/SCRAM usernames+passwords or TLS client certificates.", "note_vi": "Cho client xác thực vào MSK bằng IAM role/credential (giống gọi API AWS khác) thay vì tự quản lý user/password SASL/SCRAM hay chứng chỉ TLS client riêng - đơn giản hơn để vận hành và audit.", "example": "IAM policy cấp quyền kafka-cluster:Connect / *Topic / *Group giới hạn theo cluster ARN."}'::jsonb),
  ('data', 'MSK nằm trong VPC, không public', '{"back": "MSK brokers are deployed into your VPC''s private subnets - by design there is no public endpoint; a client must be inside the VPC (or connected via VPN/peering) to reach it.", "note_vi": "Broker MSK được triển khai vào private subnet của VPC - theo thiết kế không có endpoint public; client phải nằm trong VPC (hoặc kết nối qua VPN/peering/Transit Gateway) mới gọi được.", "example": "Giống mô hình bảo mật của ElastiCache: không bao giờ internet-facing, security group gate truy cập theo cổng."}'::jsonb),
  ('compliance', 'PCI-DSS: phạm vi (scope)', '{"back": "PCI-DSS applies to any system that STORES, PROCESSES or TRANSMITS cardholder data (the ''CDE'') - network segmentation to shrink which systems touch card data shrinks what must be audited.", "note_vi": "PCI-DSS áp dụng cho mọi hệ thống LƯU, XỬ LÝ hoặc TRUYỀN dữ liệu thẻ (gọi là CDE - Cardholder Data Environment) - phân đoạn mạng (segmentation) để giảm số hệ thống chạm vào dữ liệu thẻ sẽ giảm phạm vi phải audit.", "example": "Đặt payment service trong VPC/subnet riêng, tách biệt với phần còn lại của app, sẽ giảm phạm vi PCI chỉ còn lại phần đó."}'::jsonb),
  ('compliance', 'SOC 2 Trust Service Criteria', '{"back": "Five criteria SOC 2 can be audited against: Security (mandatory), Availability, Confidentiality, Processing Integrity, Privacy.", "note_vi": "5 tiêu chí SOC 2 có thể được audit: Security (bắt buộc), Availability, Confidentiality, Processing Integrity, Privacy - hầu hết report SOC 2 của công ty chỉ chọn Security + 1 vài tiêu chí khác.", "example": "Một SaaS bán cho doanh nghiệp lớn thường cần Security + Availability + Confidentiality tối thiểu."}'::jsonb),
  ('compliance', 'AWS CloudTrail', '{"back": "Logs every API call made in your AWS account (who, what, when, from where) - the baseline evidence auditors ask for in both PCI-DSS and SOC 2.", "note_vi": "Ghi log mọi lời gọi API trong account AWS (ai, làm gì, lúc nào, từ đâu) - bằng chứng cơ bản mà auditor PCI-DSS và SOC 2 đều yêu cầu (yêu cầu về accountability / audit trail).", "example": "aws cloudtrail create-trail --name org-trail --s3-bucket-name my-audit-logs-bucket"}'::jsonb),
  ('compliance', 'Mã hóa at-rest & in-transit', '{"back": "Both PCI-DSS and SOC 2 require data encrypted while STORED (at rest) and while MOVING across a network (in transit - TLS/HTTPS everywhere).", "note_vi": "Cả PCI-DSS và SOC 2 đều yêu cầu dữ liệu được mã hóa khi LƯU TRỮ (at rest - vd S3 SSE, EBS encryption, RDS encryption) và khi DI CHUYỂN qua mạng (in transit - TLS/HTTPS, kể cả giữa các service nội bộ).", "example": "Một EBS volume không mã hóa chứa dữ liệu thẻ là 1 lỗi PCI-DSS tự động fail."}'::jsonb),
  ('compliance', 'Least privilege IAM', '{"back": "Every IAM role/user should have ONLY the permissions it actually needs - the #1 thing both PCI-DSS and SOC 2 auditors check IAM policies for.", "note_vi": "Mọi IAM role/user chỉ nên có ĐÚNG quyền cần dùng, không hơn - điều đầu tiên auditor PCI-DSS và SOC 2 kiểm tra trên IAM policy (quyền ''*'' quá rộng là lỗi kinh điển bị nêu ra).", "example": "Một finding thường gặp: EC2 role có s3:* trên Resource:* thay vì giới hạn theo 1 bucket/prefix."}'::jsonb),
  ('compliance', 'AWS Config & GuardDuty', '{"back": "AWS Config continuously records resource configuration and flags drift from a desired baseline. GuardDuty continuously watches for threats/anomalies. Both produce ''continuous monitoring'' evidence.", "note_vi": "AWS Config liên tục ghi lại cấu hình resource và báo khi lệch khỏi chuẩn mong muốn (vd ''security group mở 0.0.0.0/0''). GuardDuty liên tục theo dõi dấu hiệu bất thường/đe dọa. Cả 2 tạo ra bằng chứng ''continuous monitoring'' mà auditor cần.", "example": "Một Config rule có thể tự động báo ngay khi có S3 bucket mới tạo bị public trong vài phút."}'::jsonb),
  ('compliance', 'WAF cho ứng dụng public-facing', '{"back": "AWS WAF filters HTTP(S) requests to a public app against rules (SQLi, XSS, rate limiting, IP reputation) BEFORE they reach the app - a required/expected control for a PCI-scoped web app.", "note_vi": "AWS WAF lọc request HTTP(S) tới app public (ALB/CloudFront/API Gateway) theo rule (SQLi, XSS, rate limiting, danh sách IP xấu) TRƯỚC KHI chạm vào app - control bắt buộc/được kỳ vọng cho web app trong phạm vi PCI.", "example": "Một managed rule group chặn OWASP Top 10 là 1 baseline WAF phổ biến cho PCI-DSS."}'::jsonb),
  ('cdn_security', 'Cloudflare DNS Proxy (orange cloud) vs DNS Only (grey cloud)', '{"back": "Orange cloud = Cloudflare proxies traffic (hides your origin IP, adds CDN/WAF). Grey cloud = DNS only, visitors connect DIRECTLY to your origin IP (no protection).", "note_vi": "Orange cloud: Cloudflare làm proxy (ẩn IP origin, có CDN/WAF/cache). Grey cloud: chỉ phân giải DNS, khách truy cập THẲNG vào IP origin (không được bảo vệ gì) - dễ vô tình để sót 1 record ở trạng thái grey.", "example": "Một ''api'' A-record để grey sẽ lộ IP thực của EC2/ALB trực tiếp, bỏ qua hoàn toàn WAF của Cloudflare."}'::jsonb),
  ('cdn_security', 'Cloudflare SSL/TLS mode: Full (strict) là chuẩn', '{"back": "Off/Flexible encrypt only visitor<->Cloudflare (Cloudflare<->origin stays plaintext). Full encrypts both legs but doesn''t validate the origin cert. Full (strict) encrypts both legs AND validates the origin''s cert.", "note_vi": "Off/Flexible chỉ mã hóa đoạn khách↔Cloudflare (đoạn Cloudflare↔origin vẫn plaintext - rủi ro). Full mã hóa cả 2 đoạn nhưng không kiểm tra chứng chỉ origin. Full (strict) mã hóa cả 2 đoạn VÀ kiểm tra chứng chỉ origin - cấu hình đúng cho origin AWS thực.", "example": "Kết hợp Full (strict) với chứng chỉ AWS Certificate Manager (ACM) trên ALB/origin, hoặc chứng chỉ Cloudflare Origin CA."}'::jsonb),
  ('cdn_security', 'Giới hạn origin AWS chỉ nhận traffic từ Cloudflare', '{"back": "Even with Cloudflare proxying, the AWS origin is still reachable directly by its real IP unless you restrict it - allow inbound 80/443 ONLY from Cloudflare''s published IP ranges.", "note_vi": "Dù đã proxy qua Cloudflare, origin AWS (security group của ALB/EC2) vẫn có thể bị truy cập thẳng bằng IP thực nếu không giới hạn - chỉ mở inbound 80/443 từ dải IP công khai của Cloudflare, không mở 0.0.0.0/0.", "example": "Lấy dải IP hiện tại của Cloudflare (https://www.cloudflare.com/ips/) và chỉ allowlist đúng các CIDR đó trong Security Group."}'::jsonb),
  ('cdn_security', 'Cloudflare Tunnel (cloudflared)', '{"back": "An outbound-only agent run on the origin that connects OUT to Cloudflare - so you don''t need to open ANY inbound port on the AWS side at all.", "note_vi": "Agent chạy trên origin, chỉ kết nối RA NGOÀI tới Cloudflare - nên không cần mở BẤT KỲ cổng inbound nào ở phía AWS (kể cả 443), cùng tinh thần với EC2 không public IP + SSM.", "example": "cloudflared tunnel run <tunnel-name>   (không cần rule inbound Security Group nào cả)"}'::jsonb),
  ('cdn_security', 'Cloudflare WAF & Rate Limiting', '{"back": "Rules evaluated BEFORE a request reaches the AWS origin - blocking malicious patterns or excessive rates at the edge saves origin compute.", "note_vi": "Rule được xét TRƯỚC KHI request chạm tới origin AWS - chặn pattern độc hại hoặc request quá nhiều ngay tại edge Cloudflare giúp tiết kiệm compute của origin và giảm lượng request lọt tới AWS WAF/ALB.", "example": "Một rate-limiting rule 100 req/min mỗi IP trên /login chặn credential-stuffing trước khi lọt tới AWS."}'::jsonb)
) AS c(deck_slug, front, payload)
JOIN decks d ON d.slug = c.deck_slug AND d.subject_id = (SELECT id FROM subjects WHERE slug = 'aws')
ON CONFLICT DO NOTHING;

-- practice questions
INSERT INTO cards (deck_id, kind, front, payload, source)
SELECT d.id, 'mcq', q.front, q.payload, 'seed'
FROM (VALUES
  ('A route table for a subnet sends 0.0.0.0/0 to an Internet Gateway. What does that make the subnet?', '{"choices": ["Public", "Private", "Isolated", "It depends on the EC2''s own public IP setting"], "answer": 0, "explanation": "A subnet is public purely because its route table sends internet-bound traffic to an Internet Gateway - not because of any individual instance''s setting."}'::jsonb),
  ('An EC2 in a private subnet needs to run `apt update` but must NEVER be reachable from the internet. What do you add?', '{"choices": ["A NAT Gateway (route 0.0.0.0/0 to it)", "An Internet Gateway attached to that subnet", "An Elastic IP on the instance", "Nothing - private subnets already have outbound internet"], "answer": 0, "explanation": "A NAT Gateway allows outbound-only internet access; an Internet Gateway would make the subnet reachable both ways, which is what must be avoided here."}'::jsonb),
  ('What is the correct way to SSH into an EC2 with no public IP and no open port 22?', '{"choices": ["AWS Systems Manager Session Manager", "Assign it an Elastic IP temporarily", "Open port 22 to 0.0.0.0/0 just for the session", "It is impossible without a public IP"], "answer": 0, "explanation": "SSM Session Manager connects via the SSM Agent''s outbound HTTPS connection - no inbound port or public IP needed at all."}'::jsonb),
  ('Which AWS control, if left at its default setting, overrides a bucket policy that tries to make an S3 object public?', '{"choices": ["S3 Block Public Access", "Bucket Versioning", "A VPC Endpoint", "CloudTrail"], "answer": 0, "explanation": "S3 Block Public Access is on by default for new buckets and overrides any ACL/policy that would otherwise make an object public."}'::jsonb),
  ('Why should an EC2 instance use an IAM role (instance profile) instead of a hardcoded access key?', '{"choices": ["The role''s credentials are temporary and auto-rotated", "Roles are the only way to reach S3", "Access keys don''t work inside a VPC", "IAM roles are free, access keys are billed"], "answer": 0, "explanation": "Instance-profile credentials are short-lived and rotate automatically, removing the risk of a leaked long-lived secret on the instance."}'::jsonb),
  ('Why is ElastiCache (Redis/Memcached) never reachable from the public internet by default?', '{"choices": ["It has no public endpoint - it only lives inside your VPC", "AWS blocks it until you pay extra", "It uses a non-standard IP protocol", "It is always placed in a public subnet with a locked security group"], "answer": 0, "explanation": "ElastiCache is designed to run entirely inside your VPC with no public endpoint; only resources with network access to that VPC can reach it."}'::jsonb),
  ('In Kafka, what guarantees message ORDER?', '{"choices": ["Order is guaranteed only within a single partition", "Order is always guaranteed across an entire topic", "Order is guaranteed per consumer group", "Kafka does not guarantee order at all, anywhere"], "answer": 0, "explanation": "Kafka guarantees ordering within one partition; across multiple partitions of the same topic there is no guaranteed global order."}'::jsonb),
  ('What does MSK IAM Authentication let a client avoid managing?', '{"choices": ["Separate SASL/SCRAM usernames and passwords or TLS client certificates", "The Kafka topic name", "The number of partitions", "The VPC CIDR block"], "answer": 0, "explanation": "With IAM auth, the client uses its existing IAM role/credentials instead of a separate SASL/SCRAM or mTLS credential set."}'::jsonb),
  ('What is the main point of PCI-DSS network segmentation?', '{"choices": ["Shrink the set of systems that are in-scope for the audit", "Make the network diagram look more professional", "Increase AWS data-transfer cost on purpose", "Avoid needing CloudTrail"], "answer": 0, "explanation": "Segmentation keeps cardholder data confined to as few systems as possible, so fewer systems fall inside the PCI-DSS audit scope (the CDE)."}'::jsonb),
  ('Which SOC 2 Trust Service Criterion is mandatory in every SOC 2 report?', '{"choices": ["Security", "Availability", "Privacy", "Processing Integrity"], "answer": 0, "explanation": "Security is the one mandatory criterion; Availability, Confidentiality, Processing Integrity and Privacy are chosen depending on the business."}'::jsonb),
  ('A Cloudflare DNS record is set to ''DNS only'' (grey cloud) instead of proxied (orange cloud). What is the risk?', '{"choices": ["Visitors connect directly to the real origin IP, bypassing Cloudflare''s WAF/CDN entirely", "The site becomes completely unreachable", "AWS blocks all traffic to that record", "Nothing - grey cloud is just as protected as orange cloud"], "answer": 0, "explanation": "Grey cloud is DNS resolution only - Cloudflare does not sit in the traffic path, so none of its protections (WAF, caching, IP hiding) apply."}'::jsonb),
  ('Why is Cloudflare SSL/TLS mode ''Full (strict)'' preferred over ''Flexible'' for a real AWS origin?', '{"choices": ["It encrypts and validates the Cloudflare-to-origin leg too, not just the visitor-to-Cloudflare leg", "It is the only mode that works with an ALB", "It removes the need for a Security Group on the origin", "It disables WAF, which is faster"], "answer": 0, "explanation": "Flexible only encrypts the visitor-to-Cloudflare leg, leaving Cloudflare-to-origin traffic in plaintext; Full (strict) encrypts both legs and validates the origin''s certificate."}'::jsonb)
) AS q(front, payload)
JOIN decks d ON d.slug = 'practice' AND d.subject_id = (SELECT id FROM subjects WHERE slug = 'aws')
ON CONFLICT DO NOTHING;

-- lab cards
INSERT INTO cards (deck_id, kind, front, payload, source)
SELECT d.id, 'lab', c.front, c.payload, 'seed'
FROM (VALUES
  ('Lab AWS-1 - VPC: Internet Gateway, subnet, route table', '{"scenario": "VPC vpc-0abc123456789de01 (CIDR 10.0.0.0/16) đã được tạo sẵn. Bạn cần dựng đầy đủ hạ tầng mạng cần thiết để có 1 public subnet ra được internet.", "difficulty": "co_ban", "steps": [{"prompt": "Tạo mới 1 Internet Gateway.", "type": "command", "hint": "aws ec2 create-internet-gateway", "patterns": ["aws\\s+ec2\\s+create-internet-gateway"], "explanation": "create-internet-gateway tạo 1 IGW độc lập, chưa gắn vào VPC nào cả - phải attach ở bước sau."}, {"prompt": "Gắn Internet Gateway igw-0123456789abcdef0 vào VPC vpc-0abc123456789de01.", "type": "command", "hint": "aws ec2 attach-internet-gateway --vpc-id vpc-0abc123456789de01 --internet-gateway-id igw-0123456789abcdef0", "patterns": ["aws\\s+ec2\\s+attach-internet-gateway\\s+--vpc-id\\s+vpc-0abc123456789de01\\s+--internet-gateway-id\\s+igw-0123456789abcdef0", "aws\\s+ec2\\s+attach-internet-gateway\\s+--internet-gateway-id\\s+igw-0123456789abcdef0\\s+--vpc-id\\s+vpc-0abc123456789de01"], "explanation": "1 VPC chỉ attach được 1 IGW; phải attach-internet-gateway trước khi route table có thể trỏ tới nó."}, {"prompt": "Tạo 1 subnet mới trong VPC đó, CIDR 10.0.1.0/24 (sẽ dùng làm public subnet).", "type": "command", "hint": "aws ec2 create-subnet --vpc-id vpc-0abc123456789de01 --cidr-block 10.0.1.0/24", "patterns": ["aws\\s+ec2\\s+create-subnet\\s+--vpc-id\\s+vpc-0abc123456789de01\\s+--cidr-block\\s+10\\.0\\.1\\.0/24", "aws\\s+ec2\\s+create-subnet\\s+--cidr-block\\s+10\\.0\\.1\\.0/24\\s+--vpc-id\\s+vpc-0abc123456789de01"], "explanation": "create-subnet tạo subnet với 1 dải CIDR con nằm trong dải CIDR của VPC (10.0.0.0/16)."}, {"prompt": "Thêm route 0.0.0.0/0 trỏ về Internet Gateway igw-0123456789abcdef0 vào route table rtb-0a1b2c3d4e5f67890 (route table này sẽ gắn cho subnet public).", "type": "command", "hint": "aws ec2 create-route --route-table-id rtb-0a1b2c3d4e5f67890 --destination-cidr-block 0.0.0.0/0 --gateway-id igw-0123456789abcdef0", "patterns": ["aws\\s+ec2\\s+create-route\\s+--route-table-id\\s+rtb-0a1b2c3d4e5f67890\\s+--destination-cidr-block\\s+0\\.0\\.0\\.0/0\\s+--gateway-id\\s+igw-0123456789abcdef0", "aws\\s+ec2\\s+create-route\\s+--destination-cidr-block\\s+0\\.0\\.0\\.0/0\\s+--gateway-id\\s+igw-0123456789abcdef0\\s+--route-table-id\\s+rtb-0a1b2c3d4e5f67890"], "explanation": "Chính route này (0.0.0.0/0 -> igw) là thứ duy nhất biến 1 subnet thành ''public'' - không có gì khác về mặt cấu hình."}, {"prompt": "Gắn (associate) route table rtb-0a1b2c3d4e5f67890 vào subnet subnet-0fedcba9876543210 vừa tạo, để subnet này thực sự là public.", "type": "command", "hint": "aws ec2 associate-route-table --route-table-id rtb-0a1b2c3d4e5f67890 --subnet-id subnet-0fedcba9876543210", "patterns": ["aws\\s+ec2\\s+associate-route-table\\s+--route-table-id\\s+rtb-0a1b2c3d4e5f67890\\s+--subnet-id\\s+subnet-0fedcba9876543210", "aws\\s+ec2\\s+associate-route-table\\s+--subnet-id\\s+subnet-0fedcba9876543210\\s+--route-table-id\\s+rtb-0a1b2c3d4e5f67890"], "explanation": "Tạo route đúng chưa đủ - phải associate route table đó với đúng subnet mới có hiệu lực trên subnet ấy."}], "reference": "## VPC Networking: Internet Gateway, Subnet, Route Table\n\n**Trình tự chuẩn để có 1 public subnet:**\n1. `create-internet-gateway` (độc lập, chưa gắn VPC nào)\n2. `attach-internet-gateway --vpc-id ... --internet-gateway-id ...` (gắn IGW vào đúng 1 VPC)\n3. `create-subnet --vpc-id ... --cidr-block ...` (CIDR subnet phải nằm trong CIDR VPC)\n4. `create-route --route-table-id ... --destination-cidr-block 0.0.0.0/0 --gateway-id <igw-id>` (đây là điều KIỆN DUY NHẤT biến route table thành ''public'')\n5. `associate-route-table --route-table-id ... --subnet-id ...` (gắn route table đó vào đúng subnet)\n\n**Mental model:** subnet không tự nó ''public'' hay ''private'' - nó public/private hoàn toàn do route table của nó đang trỏ 0.0.0.0/0 về đâu (IGW = public, NAT Gateway = private có thể ra ngoài một chiều, không có route = isolated hoàn toàn)."}'::jsonb),
  ('Lab AWS-2 - EC2 không Public IP + SSM Session Manager', '{"scenario": "Cần launch 1 EC2 app server trong private subnet subnet-0a1b2c3d4e5f67890, không được có public IP, và phải truy cập được mà không mở port 22.", "difficulty": "trung_binh", "steps": [{"prompt": "Launch EC2 (AMI ami-0abcdef1234567890, loại t3.micro) vào subnet private đó, KHÔNG gán public IP, và đính kèm IAM instance profile tên SSMInstanceProfile (đã có policy AmazonSSMManagedInstanceCore).", "type": "command", "hint": "aws ec2 run-instances --image-id ami-0abcdef1234567890 --instance-type t3.micro --subnet-id subnet-0a1b2c3d4e5f67890 --no-associate-public-ip-address --iam-instance-profile Name=SSMInstanceProfile", "patterns": ["aws\\s+ec2\\s+run-instances(?=.*--image-id\\s+ami-0abcdef1234567890)(?=.*--instance-type\\s+t3\\.micro)(?=.*--subnet-id\\s+subnet-0a1b2c3d4e5f67890)(?=.*--no-associate-public-ip-address)(?=.*--iam-instance-profile\\s+Name=SSMInstanceProfile).*"], "explanation": "Không có --associate-public-ip-address (hoặc dùng --no-associate-public-ip-address) + không có Elastic IP = instance không có địa chỉ internet trực tiếp nào."}, {"prompt": "Kiểm tra xem SSM Agent của instance i-0123456789abcdef0 đã đăng ký ''online'' với SSM chưa.", "type": "command", "hint": "aws ssm describe-instance-information --filters Key=InstanceIds,Values=i-0123456789abcdef0", "patterns": ["aws\\s+ssm\\s+describe-instance-information\\s+--filters\\s+Key=InstanceIds,Values=i-0123456789abcdef0"], "output": "{\"InstanceInformationList\": [{\"InstanceId\": \"i-0123456789abcdef0\", \"PingStatus\": \"Online\", \"PlatformType\": \"Linux\"}]}", "explanation": "Instance phải online trên SSM (agent đã kết nối được ra ngoài qua HTTPS + có đúng IAM role) trước khi start-session hoạt động được."}, {"prompt": "Mở 1 session shell tương tác vào instance i-0123456789abcdef0 qua SSM (không cần SSH, không cần port 22).", "type": "command", "hint": "aws ssm start-session --target i-0123456789abcdef0", "patterns": ["aws\\s+ssm\\s+start-session\\s+--target\\s+i-0123456789abcdef0"], "explanation": "start-session mở 1 kênh shell qua SSM Agent - hoàn toàn không đi qua port 22 hay cần public IP."}, {"prompt": "Agent SSM trên EC2 cần IAM permission nào để đăng ký và hoạt động được (qua instance profile)?", "type": "choice", "choices": ["Managed policy AmazonSSMManagedInstanceCore gắn qua instance profile", "AdministratorAccess trên toàn account", "Không cần quyền IAM nào, chỉ cần mở port 22", "AmazonS3FullAccess"], "answer": 0, "explanation": "SSM Agent cần role gắn vào instance có chứa managed policy AmazonSSMManagedInstanceCore - policy này cấp vừng quyền tối thiểu để agent gọi về SSM service, không phải quyền admin toàn AWS."}], "reference": "## EC2 không Public IP + AWS Systems Manager Session Manager\n\n**Điều kiện để 1 EC2 không có public IP mà vẫn truy cập được an toàn:**\n1. Launch với `--no-associate-public-ip-address` (hoặc đơn giản là không gán Elastic IP, không auto-assign) trong private subnet.\n2. Gắn IAM instance profile có managed policy **AmazonSSMManagedInstanceCore** - đây là quyền tối thiểu để SSM Agent (có sẵn trên Amazon Linux 2/2023) kết nối ra ngoài qua HTTPS (outbound, không phải inbound).\n3. Kiểm tra instance đã ''Online'' với `describe-instance-information` trước khi `start-session`.\n4. `aws ssm start-session --target <instance-id>` mở shell - hoàn toàn không qua port 22, không cần bastion host, không cần VPN.\n\n**Mental model:** SSM đảo ngược hướng kết nối - thay vì ''ai đó từ ngoài SSH vào'', chính EC2 tự gọi RA NGOÀI (outbound HTTPS) tới SSM service, nên không cần mở bất kỳ port inbound nào."}'::jsonb),
  ('Lab AWS-3 - S3: bucket, block public access, versioning, encryption', '{"scenario": "Cần tạo 1 bucket S3 tên my-company-data-2026 để lưu dữ liệu nhạy cảm, phải đảm bảo không thể vô tình bị public và được mã hóa đúng chuẩn.", "difficulty": "co_ban", "steps": [{"prompt": "Tạo bucket S3 tên my-company-data-2026 trong region ap-southeast-1.", "type": "command", "hint": "aws s3 mb s3://my-company-data-2026 --region ap-southeast-1", "patterns": ["aws\\s+s3\\s+mb\\s+s3://my-company-data-2026\\s+--region\\s+ap-southeast-1"], "explanation": "s3 mb (make bucket) tạo bucket; tên bucket phải duy nhất toàn cầu trên toàn AWS, không chỉ trong account của bạn."}, {"prompt": "Chặn hoàn toàn mọi khả năng bucket này bị public (cả qua ACL và qua policy).", "type": "command", "hint": "aws s3api put-public-access-block --bucket my-company-data-2026 --public-access-block-configuration BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=true,RestrictPublicBuckets=true", "patterns": ["aws\\s+s3api\\s+put-public-access-block\\s+--bucket\\s+my-company-data-2026\\s+--public-access-block-configuration\\s+BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=true,RestrictPublicBuckets=true"], "explanation": "Cả 4 cờ đều phải true để chặn triệt để mọi đường khiến bucket/object vô tình thành public - thiếu 1 cờ vẫn còn kẻ hở."}, {"prompt": "Bật Versioning cho bucket, để chống ghi đè/xóa nhầm dữ liệu.", "type": "command", "hint": "aws s3api put-bucket-versioning --bucket my-company-data-2026 --versioning-configuration Status=Enabled", "patterns": ["aws\\s+s3api\\s+put-bucket-versioning\\s+--bucket\\s+my-company-data-2026\\s+--versioning-configuration\\s+Status=Enabled"], "explanation": "Khi đã Enabled, 1 lệnh delete chỉ tạo ''delete marker'', bản cũ của object vẫn còn truy xuất lại được."}, {"prompt": "Upload file report.pdf lên bucket, mã hóa SSE-KMS với key alias/my-key.", "type": "command", "hint": "aws s3 cp report.pdf s3://my-company-data-2026/report.pdf --sse aws:kms --sse-kms-key-id alias/my-key", "patterns": ["aws\\s+s3\\s+cp\\s+report\\.pdf\\s+s3://my-company-data-2026/report\\.pdf\\s+--sse\\s+aws:kms\\s+--sse-kms-key-id\\s+alias/my-key"], "explanation": "--sse aws:kms chọn SSE-KMS (thay vì SSE-S3 mặc định); --sse-kms-key-id chỉ định rõ key KMS nào được dùng, để việc truy cập key cũng audit được riêng."}, {"prompt": "Tạo 1 presigned URL cho object report.pdf, hết hạn sau 3600 giây (1 giờ), để 1 người ngoài download mà không cần credential AWS.", "type": "command", "hint": "aws s3 presign s3://my-company-data-2026/report.pdf --expires-in 3600", "patterns": ["aws\\s+s3\\s+presign\\s+s3://my-company-data-2026/report\\.pdf\\s+--expires-in\\s+3600"], "explanation": "presign tạo URL tạm có ký (signed) bằng chính credential của bạn nhưng không làm bucket public - URL chỉ dùng được cho ĐÚNG object đó, trong đúng thời hạn."}], "reference": "## S3: Bucket, Block Public Access, Versioning, SSE-KMS, Presigned URL\n\n**Thứ tự nên làm khi tạo 1 bucket chứa dữ liệu nhạy cảm:**\n1. `s3 mb s3://<tên-bucket>` - tên phải duy nhất toàn cầu.\n2. `s3api put-public-access-block` với CẢ 4 cờ `true` - đây là lớp chặn quan trọng nhất, ghi đè bất kỳ bucket policy/ACL nào có làm object public.\n3. `s3api put-bucket-versioning --versioning-configuration Status=Enabled` - chống xóa/ghi đè nhầm.\n4. Upload với `--sse aws:kms --sse-kms-key-id <alias>` (SSE-KMS) thay vì để mặc định SSE-S3, để việc truy cập key cũng được log/audit riêng - cần cho PCI/SOC 2.\n5. `s3 presign` khi cần chia sẻ 1 object cụ thể ra ngoài mà không public cả bucket và không cần cấp credential AWS cho người nhận."}'::jsonb),
  ('Lab AWS-4 - Chạy Docker trong EC2 (ECR + docker run)', '{"scenario": "EC2 Amazon Linux 2023 đã chạy sẵn, cần cài Docker và deploy 1 container từ image riêng tư lưu trong ECR (account 123456789012, region ap-southeast-1).", "difficulty": "trung_binh", "steps": [{"prompt": "Cài Docker engine trên Amazon Linux 2023.", "type": "command", "hint": "sudo dnf install -y docker", "patterns": ["sudo\\s+dnf\\s+install\\s+-y\\s+docker"], "explanation": "Amazon Linux 2023 dùng dnf (không phải yum/apt); -y để không phải xác nhận từng bước."}, {"prompt": "Bật (enable) và chạy ngay (start) Docker daemon, để nó tự khởi động lại khi EC2 reboot.", "type": "command", "hint": "sudo systemctl enable --now docker", "patterns": ["sudo\\s+systemctl\\s+enable\\s+--now\\s+docker"], "explanation": "--now vừa enable (tự chạy khi boot) vừa start ngay trong 1 lệnh, không cần gõ systemctl start riêng."}, {"prompt": "Đăng nhập vào ECR private registry của account 123456789012 tại region ap-southeast-1.", "type": "command", "hint": "aws ecr get-login-password --region ap-southeast-1 | docker login --username AWS --password-stdin 123456789012.dkr.ecr.ap-southeast-1.amazonaws.com", "patterns": ["aws\\s+ecr\\s+get-login-password\\s+--region\\s+ap-southeast-1\\s*\\|\\s*docker\\s+login\\s+--username\\s+AWS\\s+--password-stdin\\s+123456789012\\.dkr\\.ecr\\.ap-southeast-1\\.amazonaws\\.com"], "explanation": "get-login-password trả về token tạm (hết hạn sau 12 giờ) chứ không phải mật khẩu cố định - pipe thẳng vào docker login, không lưu ra file."}, {"prompt": "Pull image app:latest từ registry ECR đó về EC2.", "type": "command", "hint": "docker pull 123456789012.dkr.ecr.ap-southeast-1.amazonaws.com/app:latest", "patterns": ["docker\\s+pull\\s+123456789012\\.dkr\\.ecr\\.ap-southeast-1\\.amazonaws\\.com/app:latest"], "explanation": "Tên image khi pull từ ECR luôn có dạng <account>.dkr.ecr.<region>.amazonaws.com/<repo>:<tag>."}, {"prompt": "Chạy container từ image đó: đặt tên ''webapp'', map port 8080 (host) vào 80 (container), và tự khởi động lại khi container crash/EC2 reboot.", "type": "command", "hint": "docker run -d --name webapp -p 8080:80 --restart unless-stopped 123456789012.dkr.ecr.ap-southeast-1.amazonaws.com/app:latest", "patterns": ["docker\\s+run\\s+(?=.*-d)(?=.*--name\\s+webapp)(?=.*-p\\s+8080:80)(?=.*--restart\\s+unless-stopped)(?=.*123456789012\\.dkr\\.ecr\\.ap-southeast-1\\.amazonaws\\.com/app:latest).*"], "explanation": "--restart unless-stopped là lựa chọn phổ biến trên EC2 production: tự chạy lại khi crash hoặc EC2 reboot, nhưng không chạy lại nếu bạn tự tay stop nó."}], "reference": "## Chạy Docker trong EC2: cài đặt + ECR + docker run\n\n**Thứ tự chuẩn:**\n1. Cài Docker (tên package/cách cài khác theo AMI: Amazon Linux 2023 dùng `dnf install docker`; Ubuntu dùng `apt install docker.io` hoặc Docker''s official repo).\n2. `systemctl enable --now docker` để daemon tự chạy lại sau reboot.\n3. Với image riêng tư trong ECR: phải `get-login-password` (token 12h) rồi pipe vào `docker login` - không có bước này sẽ bị ''no basic auth credentials'' khi pull.\n4. `docker pull <account>.dkr.ecr.<region>.amazonaws.com/<repo>:<tag>`.\n5. `docker run -d --name <tên> -p <host>:<container> --restart unless-stopped <image>` - bỏ --restart là quên 1 thứ rất dễ gây ''container biến mất sau khi EC2 reboot'' trong thực chiến.\n\n**Lưu ý IAM:** EC2 cần IAM role (instance profile) có quyền kéo image từ ECR (vd AmazonEC2ContainerRegistryReadOnly) - không nên tạo IAM user/access key riêng chỉ để pull image."}'::jsonb),
  ('Lab AWS-5 - ElastiCache Redis trong VPC', '{"scenario": "App cần 1 Redis cache, chỉ được truy cập từ trong VPC (private subnet subnet-0aaaaaaaaaaaaaaaa và subnet-0bbbbbbbbbbbbbbbb), security group của app là sg-0dddddddddddddddd.", "difficulty": "trung_binh", "steps": [{"prompt": "Tạo 1 cache subnet group tên app-cache-subnets, dùng 2 private subnet đã cho.", "type": "command", "hint": "aws elasticache create-cache-subnet-group --cache-subnet-group-name app-cache-subnets --cache-subnet-group-description \"App cache subnets\" --subnet-ids subnet-0aaaaaaaaaaaaaaaa subnet-0bbbbbbbbbbbbbbbb", "patterns": ["aws\\s+elasticache\\s+create-cache-subnet-group(?=.*--cache-subnet-group-name\\s+app-cache-subnets)(?=.*subnet-0aaaaaaaaaaaaaaaa)(?=.*subnet-0bbbbbbbbbbbbbbbb).*"], "explanation": "ElastiCache luôn chạy trong 1 subnet group (tập hợp subnet) - đảm bảo nó được đặt trong private subnet, không hề có tùy chọn để nó public."}, {"prompt": "Tạo Redis cluster tên app-cache, node type cache.t3.micro, 1 node, dùng subnet group vừa tạo và security group sg-0cccccccccccccccc (sẽ gắn rule mở cổng ở bước sau).", "type": "command", "hint": "aws elasticache create-cache-cluster --cache-cluster-id app-cache --engine redis --cache-node-type cache.t3.micro --num-cache-nodes 1 --cache-subnet-group-name app-cache-subnets --security-group-ids sg-0cccccccccccccccc", "patterns": ["aws\\s+elasticache\\s+create-cache-cluster(?=.*--cache-cluster-id\\s+app-cache)(?=.*--engine\\s+redis)(?=.*--cache-subnet-group-name\\s+app-cache-subnets)(?=.*sg-0cccccccccccccccc).*"], "explanation": "--engine redis chọn Redis (không phải memcached); security-group-ids là security group gắn vào cache, khác với security group của app gọi tới nó."}, {"prompt": "Mở cổng 6379 trên security group của cache (sg-0cccccccccccccccc), CHỈ cho phép từ security group của app (sg-0dddddddddddddddd) - không mở cho 0.0.0.0/0.", "type": "command", "hint": "aws ec2 authorize-security-group-ingress --group-id sg-0cccccccccccccccc --protocol tcp --port 6379 --source-group sg-0dddddddddddddddd", "patterns": ["aws\\s+ec2\\s+authorize-security-group-ingress(?=.*--group-id\\s+sg-0cccccccccccccccc)(?=.*--port\\s+6379)(?=.*--source-group\\s+sg-0dddddddddddddddd).*"], "explanation": "--source-group (thay vì --cidr) giới hạn nguồn được phép chỉ là các instance mang security group đó - chính xác hơn và an toàn hơn rất nhiều so với mở theo dải IP."}, {"prompt": "Từ EC2 trong app, kết nối thử tới Redis endpoint app-cache.xxxxx.cache.amazonaws.com cổng 6379 bằng redis-cli.", "type": "command", "hint": "redis-cli -h app-cache.xxxxx.cache.amazonaws.com -p 6379", "patterns": ["redis-cli\\s+-h\\s+app-cache\\.xxxxx\\.cache\\.amazonaws\\.com\\s+-p\\s+6379"], "explanation": "-h chỉ host (endpoint của cache), -p chỉ port - redis-cli chỉ kết nối thành công nếu EC2 nằm trong (hoặc có route tới) VPC đó và security group cho phép."}], "reference": "## ElastiCache Redis: subnet group, security group, kết nối\n\n**Thứ tự chuẩn:**\n1. `create-cache-subnet-group` - khai báo cache sẽ nằm trong những subnet nào (luôn là private subnet trong thực tế).\n2. `create-cache-cluster --engine redis ...` gắn với subnet group + security group.\n3. Mở cổng cache (Redis 6379 / Memcached 11211) trên security group của cache, dùng `--source-group <sg-của-app>` - KHÔNG BAO GIỜ `--cidr 0.0.0.0/0`.\n4. Kết nối từ app bằng `redis-cli -h <endpoint> -p 6379` hoặc thư viện client (ioredis, redis-py...).\n\n**Mental model:** ElastiCache không có ''ở public/private'' như EC2 - nó mặc định KHÔNG BAO GIỜ có endpoint công khai, chỉ có thể gọi được từ trong (hoặc kết nối tới) chính VPC đó, nên ''bảo mật theo mạng'' (network-level) là lớp phòng thủ đầu tiên, security group là lớp thứ hai."}'::jsonb),
  ('Lab AWS-6 - MSK (Managed Kafka): tạo cluster, topic, producer/consumer', '{"scenario": "Hệ thống cần 1 Kafka topic ''orders'' để các service bán hàng gửi/đọc sự kiện đơn hàng, chạy trên AWS MSK.", "difficulty": "nang_cao", "steps": [{"prompt": "Tạo MSK cluster tên orders-cluster, kafka version 3.5.1, 3 broker node, cấu hình broker lấy từ file broker-info.json (chứa subnet + security group).", "type": "command", "hint": "aws kafka create-cluster --cluster-name orders-cluster --kafka-version 3.5.1 --number-of-broker-nodes 3 --broker-node-group-info file://broker-info.json", "patterns": ["aws\\s+kafka\\s+create-cluster(?=.*--cluster-name\\s+orders-cluster)(?=.*--kafka-version\\s+3\\.5\\.1)(?=.*--number-of-broker-nodes\\s+3)(?=.*--broker-node-group-info\\s+file://broker-info\\.json).*"], "explanation": "broker-node-group-info (file JSON riêng) là nơi khai báo subnet + security group cho các broker - giống ElastiCache, MSK cũng chỉ sống trong VPC, không có tùy chọn public."}, {"prompt": "Lấy địa chỉ bootstrap brokers của cluster có ARN arn:aws:kafka:ap-southeast-1:123456789012:cluster/orders-cluster/abcd1234, để client biết kết nối vào đâu.", "type": "command", "hint": "aws kafka get-bootstrap-brokers --cluster-arn arn:aws:kafka:ap-southeast-1:123456789012:cluster/orders-cluster/abcd1234", "patterns": ["aws\\s+kafka\\s+get-bootstrap-brokers\\s+--cluster-arn\\s+arn:aws:kafka:ap-southeast-1:123456789012:cluster/orders-cluster/abcd1234"], "explanation": "Khác với Kafka tự quản lý (chỉ cần biết IP broker), với MSK bạn phải gọi API này để lấy đúng địa chỉ bootstrap - địa chỉ này có thể thay đổi khi AWS patch/scale cluster."}, {"prompt": "Tạo topic ''orders'' với 6 partition, replication factor 3, trên broker b-1.orders-cluster.xxxx.kafka.ap-southeast-1.amazonaws.com:9092.", "type": "command", "hint": "kafka-topics.sh --create --topic orders --partitions 6 --replication-factor 3 --bootstrap-server b-1.orders-cluster.xxxx.kafka.ap-southeast-1.amazonaws.com:9092", "patterns": ["kafka-topics\\.sh\\s+--create(?=.*--topic\\s+orders)(?=.*--partitions\\s+6)(?=.*--replication-factor\\s+3)(?=.*--bootstrap-server\\s+b-1\\.orders-cluster\\.xxxx\\.kafka\\.ap-southeast-1\\.amazonaws\\.com:9092).*"], "explanation": "6 partition cho phép tối đa 6 consumer trong cùng 1 group đọc song song; replication-factor 3 nghĩa là mỗi partition được sao lưu trên 3 broker khác nhau để chịu lỗi."}, {"prompt": "Gửi thử 1 message test vào topic orders qua console producer.", "type": "command", "hint": "kafka-console-producer.sh --topic orders --bootstrap-server b-1.orders-cluster.xxxx.kafka.ap-southeast-1.amazonaws.com:9092", "patterns": ["kafka-console-producer\\.sh\\s+--topic\\s+orders\\s+--bootstrap-server\\s+b-1\\.orders-cluster\\.xxxx\\.kafka\\.ap-southeast-1\\.amazonaws\\.com:9092"], "explanation": "console-producer mở 1 prompt nhập từng dòng, mỗi dòng Enter sẽ gửi 1 message vào topic - dùng để test nhanh, không dùng trong production code."}, {"prompt": "Đọc lại toàn bộ message trong topic orders từ đầu (từ message đầu tiên, không chỉ message mới).", "type": "command", "hint": "kafka-console-consumer.sh --topic orders --from-beginning --bootstrap-server b-1.orders-cluster.xxxx.kafka.ap-southeast-1.amazonaws.com:9092", "patterns": ["kafka-console-consumer\\.sh(?=.*--topic\\s+orders)(?=.*--from-beginning)(?=.*--bootstrap-server\\s+b-1\\.orders-cluster\\.xxxx\\.kafka\\.ap-southeast-1\\.amazonaws\\.com:9092).*"], "explanation": "--from-beginning đọc lại từ offset 0; bỏ cờ này thì consumer chỉ nhận message MỚI gửi kể từ lúc nó kết nối, bỏ qua hết lịch sử cũ."}], "reference": "## AWS MSK (Managed Kafka): tạo cluster, topic, producer/consumer\n\n**Khác biệt với tự dựng Kafka:** AWS vận hành broker (patch, scale, hạ tầng) nhưng bạn vẫn làm việc với đúng khái niệm Kafka gốc.\n\n**Thứ tự chuẩn:**\n1. `aws kafka create-cluster --broker-node-group-info file://...json` - subnet + security group khai báo trong file JSON, cluster luôn nằm trong VPC, không có endpoint public.\n2. `aws kafka get-bootstrap-brokers --cluster-arn ...` - lấy đúng địa chỉ broker hiện tại (có thể đổi khi AWS scale/patch).\n3. `kafka-topics.sh --create --topic <tên> --partitions <n> --replication-factor <r>` - partitions quyết định độ song song đọc; replication-factor quyết định độ chịu lỗi.\n4. `kafka-console-producer.sh` / `kafka-console-consumer.sh --from-beginning` chỉ để test nhanh từ dòng lệnh, không phải cách production gửi/nhận message (production dùng thư viện client: kafka-python, kafkajs...).\n\n**MSK IAM Authentication** là lựa chọn được khuyến nghị cho production: client dùng IAM role/credential có sẵn thay vì phải tự quản lý user/password SASL/SCRAM riêng."}'::jsonb),
  ('Lab AWS-7 - Cloudflare trước origin AWS', '{"scenario": "Website app.example.com đang chạy trên 1 ALB AWS, muốn đặt Cloudflare phía trước để có CDN/WAF và ẩn IP origin thực.", "difficulty": "trung_binh", "steps": [{"prompt": "DNS record cho app.example.com cần ở trạng thái nào để được Cloudflare WAF/CDN bảo vệ (không phải chỉ phân giải DNS)?", "type": "choice", "choices": ["Proxied (orange cloud)", "DNS only (grey cloud)", "Cả 2 trạng thái đều được bảo vệ giống nhau", "CNAME flattening"], "answer": 0, "explanation": "Chỉ có ''Proxied'' (orange cloud) mới khiến traffic đi QUA Cloudflare - ''DNS only'' (grey cloud) khiến khách truy cập thẳng vào IP origin thực, bỏ qua hoàn toàn mọi lớp bảo vệ của Cloudflare."}, {"prompt": "Origin AWS (ALB) đã có chứng chỉ SSL hợp lệ (vd AWS Certificate Manager). SSL/TLS mode nào trên Cloudflare là đúng chuẩn trong trường hợp này?", "type": "choice", "choices": ["Full (strict)", "Flexible", "Off", "Full (không strict)"], "answer": 0, "explanation": "Full (strict) mã hóa CẢ 2 đoạn (khách↔Cloudflare VÀ Cloudflare↔origin) VÀ kiểm tra chứng chỉ origin có hợp lệ không - đây là cấu hình đúng khi origin đã có cert thực sự, không phải Flexible (bỏ qua mã hóa đoạn Cloudflare↔origin)."}, {"prompt": "Giới hạn security group sg-0eeeeeeeeeeeeeeee của ALB chỉ nhận port 443 từ 1 dải IP của Cloudflare (ví dụ 173.245.48.0/20), thay vì mở cho mọi nơi.", "type": "command", "hint": "aws ec2 authorize-security-group-ingress --group-id sg-0eeeeeeeeeeeeeeee --protocol tcp --port 443 --cidr 173.245.48.0/20", "patterns": ["aws\\s+ec2\\s+authorize-security-group-ingress(?=.*--group-id\\s+sg-0eeeeeeeeeeeeeeee)(?=.*--port\\s+443)(?=.*--cidr\\s+173\\.245\\.48\\.0/20).*"], "explanation": "Đây mới là 1 trong nhiều dải IP Cloudflare công bố (xem https://www.cloudflare.com/ips/) - thực tế phải allowlist ĐỦ toàn bộ danh sách, không chỉ 1 dải."}, {"prompt": "Thu hồi (revoke) rule inbound 443 cũ đang mở cho toàn bộ internet (0.0.0.0/0) trên cùng security group đó.", "type": "command", "hint": "aws ec2 revoke-security-group-ingress --group-id sg-0eeeeeeeeeeeeeeee --protocol tcp --port 443 --cidr 0.0.0.0/0", "patterns": ["aws\\s+ec2\\s+revoke-security-group-ingress(?=.*--group-id\\s+sg-0eeeeeeeeeeeeeeee)(?=.*--port\\s+443)(?=.*--cidr\\s+0\\.0\\.0\\.0/0).*"], "explanation": "Nếu không revoke rule 0.0.0.0/0 cũ, ai đó vẫn có thể bỏ qua Cloudflare và gọi thẳng vào origin bằng IP thực - thêm rule Cloudflare mới là chưa đủ, phải xóa rule mở rộng cũ."}, {"prompt": "Nếu muốn KHÔNG mở bất kỳ port inbound nào trên AWS mà vẫn expose được app qua Cloudflare, nên dùng cơ chế nào?", "type": "choice", "choices": ["Cloudflare Tunnel (cloudflared)", "Mở thêm port 80 để dự phòng", "Dùng NAT Gateway", "Tạo thêm 1 Elastic IP"], "answer": 0, "explanation": "Cloudflare Tunnel (cloudflared) là 1 agent chỉ kết nối RA NGOÀI (outbound) tới Cloudflare - giống tinh thần của SSM với EC2 không public IP: không cần mở bất kỳ port inbound nào cả, kể cả port 443."}], "reference": "## Cloudflare đặt trước origin AWS\n\n**Thứ tự chuẩn để bảo vệ 1 origin AWS bằng Cloudflare:**\n1. DNS record phải **Proxied (orange cloud)** - ''DNS only'' (grey cloud) bỏ qua hoàn toàn Cloudflare.\n2. SSL/TLS mode **Full (strict)** khi origin đã có cert thực (ACM hoặc Cloudflare Origin CA) - Flexible để hở Cloudflare↔origin ở dạng plaintext.\n3. Giới hạn Security Group của origin CHỈ nhận traffic từ dải IP công bố của Cloudflare (`cloudflare.com/ips/`) rồi **revoke** rule 0.0.0.0/0 cũ - thiếu bước revoke là lỗ hổng phổ biến nhất.\n4. Nếu muốn không mở inbound port nào cả: dùng **Cloudflare Tunnel (cloudflared)**, 1 agent chỉ kết nối outbound, cùng tư tưởng với SSM Session Manager bên AWS."}'::jsonb),
  ('Lab AWS-8 - Rà soát kiến trúc theo PCI-DSS & SOC 2', '{"scenario": "Kiến trúc hiện tại: EC2 payment-service nằm trong PUBLIC subnet, security group mở 0.0.0.0/0 trên mọi port; bucket S3 payment-data-2026 chứa dữ liệu thẻ chưa mã hóa; IAM role gắn vào EC2 là AdministratorAccess; chưa có CloudTrail nào được tạo.", "difficulty": "nang_cao", "steps": [{"prompt": "Vấn đề PCI-DSS lớn nhất với việc EC2 payment-service đang nằm ở PUBLIC subnet là gì?", "type": "choice", "choices": ["Không cần thiết phải internet-facing; nên chuyển vào private subnet để giảm phạm vi CDE", "Vì EC2 luôn phải đặt ở public subnet", "Public subnet chạy nhanh hơn private subnet", "Không có vấn đề gì đáng kể"], "answer": 0, "explanation": "payment-service xử lý dữ liệu thẻ (thuộc CDE - Cardholder Data Environment) không cần thiết phải internet-facing trực tiếp - đặt nó trong private subnet (truy cập qua ALB/SSM) sẽ giảm trực tiếp phạm vi hệ thống bị audit PCI-DSS."}, {"prompt": "Tạo và bật 1 CloudTrail tên org-trail, lưu log vào bucket audit-logs-bucket-2026, để có bằng chứng audit trail cơ bản.", "type": "command", "hint": "aws cloudtrail create-trail --name org-trail --s3-bucket-name audit-logs-bucket-2026", "patterns": ["aws\\s+cloudtrail\\s+create-trail(?=.*--name\\s+org-trail)(?=.*--s3-bucket-name\\s+audit-logs-bucket-2026).*"], "explanation": "create-trail chỉ TẠO trail, chưa tự động ghi log - phải gọi thêm start-logging. Đây là bằng chứng cơ bản nhất cả PCI-DSS và SOC 2 đều đòi hỏi (accountability / audit trail)."}, {"prompt": "IAM role AdministratorAccess gắn trên EC2 payment-service vi phạm nguyên tắc nào mà auditor PCI-DSS/SOC 2 luôn kiểm tra đầu tiên?", "type": "choice", "choices": ["Least privilege (nguyên tắc quyền tối thiểu)", "Defense in depth", "Encryption at rest", "Không vi phạm nguyên tắc nào"], "answer": 0, "explanation": "Least privilege - một service chỉ cần đọc/viết vào 1 bucket và gọi vài API cụ thể lại được cấp toàn quyền trên toàn account là 1 finding kinh điển trong audit, vì 1 lần bị khai thác sẽ mất quyền kiểm soát toàn bộ AWS account."}, {"prompt": "Bật server-side encryption SSE-KMS mặc định trên bucket payment-data-2026, dùng key alias/pci-key.", "type": "command", "hint": "aws s3api put-bucket-encryption --bucket payment-data-2026 --server-side-encryption-configuration ''{\"Rules\":[{\"ApplyServerSideEncryptionByDefault\":{\"SSEAlgorithm\":\"aws:kms\",\"KMSMasterKeyID\":\"alias/pci-key\"}}]}''", "patterns": ["aws\\s+s3api\\s+put-bucket-encryption(?=.*--bucket\\s+payment-data-2026)(?=.*aws:kms)(?=.*alias/pci-key).*"], "explanation": "put-bucket-encryption đặt default encryption cho CẢ bucket - mọi object upload sau này tự động được mã hóa SSE-KMS dù người upload có chỉ định hay không, giảm rủi ro quên bật mã hóa cho 1 lần upload cụ thể."}, {"prompt": "Kiểm soát nào giúp PHÁT HIỆN ngay khi 1 security group bị mở 0.0.0.0/0 ngoài ý muốn trong tương lai (thay vì phải chờ đến lần audit sau mới biết)?", "type": "choice", "choices": ["AWS Config rule theo dõi cấu hình liên tục", "Chỉ kiểm tra thủ công mỗi 6 tháng", "Không cần vì đã fix 1 lần rồi", "Đổi Security Group sang dùng Network ACL"], "answer": 0, "explanation": "AWS Config có thể gắn 1 ''rule'' tự động kiểm tra cấu hình mỗi thay đổi và báo ngay khi có security group mở 0.0.0.0/0 - đây là ''continuous monitoring'' mà cả PCI-DSS và SOC 2 đều kỳ vọng, thay vì kiểm tra thủ công định kỳ."}], "reference": "## Rà soát kiến trúc AWS theo PCI-DSS & SOC 2\n\n**4 vấn đề kinh điển hay gặp và cách fix, theo thứ tự nên làm:**\n1. **Hệ thống xử lý dữ liệu thẻ nằm ở public subnet không cần thiết** -> chuyển vào private subnet, chỉ expose qua ALB/API Gateway - giảm trực tiếp phạm vi CDE (Cardholder Data Environment) phải audit.\n2. **Chưa có CloudTrail** -> `create-trail` + `start-logging` - bằng chứng audit trail cơ bản nhất mà auditor luôn hỏi đầu tiên.\n3. **IAM role quá rộng (AdministratorAccess) trên 1 service cụ thể** -> vi phạm least privilege - thu nhỏ lại chỉ còn đúng quyền service đó cần.\n4. **Dữ liệu nhạy cảm chưa mã hóa at-rest** -> `put-bucket-encryption` với SSE-KMS làm default cho cả bucket, không phụ thuộc người upload có nhớ chỉ định hay không.\n5. **Không có continuous monitoring** -> AWS Config rule + GuardDuty, để PHÁT HIỆN drift (vd security group bị mở lại) ngay lập tức thay vì chờ audit định kỳ mới biết."}'::jsonb)
) AS c(front, payload)
JOIN decks d ON d.slug = 'labs' AND d.subject_id = (SELECT id FROM subjects WHERE slug = 'aws')
ON CONFLICT DO NOTHING;
